test("MP4 artifact and text schema owners retain exact signed words and all required fields",()=>{const ajv=new Ajv({strict:false,allErrors:true}).addSchema(schema);for(const owned of[schema,textSchema,artifactSchema]){const validate=ajv.compile(owned);expect(validate(fixture)).toBe(true);for(const value of["-9223372036854775808","9223372036854775807","0","-1"]){const input=structuredClone(fixture);input.tracks[0]!.metadata.edits[0]!.mediaTime=value;expect(validate(input)).toBe(true)}for(const value of["-9223372036854775809","9223372036854775808","-0","01","+1"]){const input=structuredClone(fixture);input.tracks[0]!.metadata.edits[0]!.mediaTime=value;expect(validate(input)).toBe(false);expect(()=>parseMp4Snapshot(input)).toThrow()}for(const key of["movie","tracks","ftyp"]){const input=structuredClone(fixture)as Record<string,unknown>;delete input[key];expect(validate(input)).toBe(false)}}});
function edit(input:SqliteDatabase,table:string,column:number,value:SqliteValue):SqliteDatabase{const output=structuredClone(input);const row=output.tables.find(entry=>entry.name===table)!.rows[0]!;(row.values as SqliteValue[])[column]=value;return output}
test("MP4 full neutral retained state and native widths agree with independent schemas",()=>{const ajv=new Ajv({strict:false,allErrors:true});const validate=ajv.compile(schema);expect(validate(fixture)).toBe(true);const snapshot=sample();expect(snapshot.movie.creationTime).toBe(18446744073709551615n);expect(snapshot.tracks[0]!.metadata.edits[0]!.mediaTime).toBe(-9223372036854775808n);expect(snapshot.tracks[0]!.codec.hevc!.generalConstraintIndicatorFlags).toBe(18446744073709551615n);for(const value of ["18446744073709551616","01","-1"]){const invalid=structuredClone(fixture);invalid.movie.creationTime=value;expect(()=>parseMp4Snapshot(invalid)).toThrow();expect(validate(invalid)).toBe(false)}});
test("MP4 authored entity tables survive physical SQLite and independent relational edits",async()=>{const snapshot=sample();const database=await mp4SnapshotToSqliteDatabase(snapshot);expect(database.tables).toHaveLength(23);expect(await mp4SnapshotFromSqliteDatabase(await importSqliteDatabase(await exportSqliteDatabase(database)))).toEqual(snapshot);const db=Database.deserialize(await exportSqliteDatabase(database));expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT creation_time FROM mp4_movie").get()).toEqual({creation_time:"18446744073709551615"});expect(db.query("SELECT count(*) AS n FROM mp4_track WHERE track_id=4294967295").get()).toEqual({n:2});expect(db.query("SELECT general_constraint_indicator_flags FROM mp4_hevc_config").get()).toEqual({general_constraint_indicator_flags:"18446744073709551615"});db.run("UPDATE mp4_movie SET creation_time='9007199254740993',title=NULL,encoder=''");db.run("UPDATE mp4_visual_sample_entry SET color_table_id=123 WHERE id=1");db.run("UPDATE mp4_sample SET data=X'FF00',sync=0 WHERE id=1");snapshot.movie.creationTime=9007199254740993n;snapshot.movie.title=null;snapshot.movie.encoder="";snapshot.tracks[0]!.metadata.visual.colorTableId=123;snapshot.tracks[0]!.samples[0]!.data=[255,0];snapshot.tracks[0]!.samples[0]!.sync=false;expect(await mp4SnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(snapshot);db.close();expect(MP4_SQLITE_SCHEMA).not.toContain("snapshot_json");});
for(const format of ["avc1","avc3","hvc1","hev1","jpeg","mjpa"]as const)test(`MP4 ${format} keeps intermediate configuration and optional null state`,async()=>{const snapshot=sample();snapshot.tracks[0]!.codec.format=format;snapshot.tracks[0]!.metadata.color!.fullRange=null;expect(await mp4SnapshotFromSqliteDatabase(await mp4SnapshotToSqliteDatabase(snapshot))).toEqual(snapshot);snapshot.tracks[0]!.metadata.color!.fullRange=true;expect(await mp4SnapshotFromSqliteDatabase(await mp4SnapshotToSqliteDatabase(snapshot))).toEqual(snapshot)});
test("MP4 rejects malformed relational ownership, ordinals, integer widths and decimal words",async()=>{const database=await mp4SnapshotToSqliteDatabase(sample());for(const[table,column,value]of[["mp4_track",1,99n],["mp4_track",2,99n],["mp4_codec",1,"unknown"],["mp4_codec",2,256n],["mp4_movie",1,"18446744073709551616"],["mp4_movie",2,"01"],["mp4_hevc_array",3,2n],["mp4_visual_sample_entry",12,-32769n],["mp4_sample",5,2147483648n]]as const)await expect(mp4SnapshotFromSqliteDatabase(edit(database,table,column,value))).rejects.toThrow();for(const table of ["mp4_ftyp","mp4_movie","mp4_movie_matrix","mp4_codec","mp4_track_metadata","mp4_visual_sample_entry","mp4_track_matrix"]){const invalid=structuredClone(database);(invalid.tables.find(entry=>entry.name===table)!.rows as unknown[]).shift();await expect(mp4SnapshotFromSqliteDatabase(invalid)).rejects.toThrow()}await expect(mp4SnapshotToSqliteDatabase(sample(),{maxRows:1})).rejects.toThrow();await expect(mp4SnapshotFromSqliteDatabase(database,{maxValueBytes:0})).rejects.toThrow()});
test("MP4 cancellation reaches large payload copies and retained occurrences",async()=>{let snapshot=sample();snapshot.tracks[0]!.samples=Array.from({length:controls.entityCount},()=>structuredClone(snapshot.tracks[0]!.samples[0]!));const cancel=new AbortController();let reached=false;await expect(mp4SnapshotToSqliteDatabase(snapshot,{signal:cancel.signal,onProgress:event=>{if(event.completed>=controls.cancelAt){reached=true;cancel.abort()}}})).rejects.toThrow();expect(reached).toBe(true);snapshot=sample();snapshot.tracks[0]!.samples[0]!.data=Array(controls.largeBlobBytes).fill(255);const database=await mp4SnapshotToSqliteDatabase(snapshot);for(const phase of ["projectSnapshot","reconstructSnapshot"]as const){const cancel=new AbortController();let reached=false;const options={signal:cancel.signal,onProgress:(event:{phase:string;completed:number;total:number})=>{if(event.phase===phase&&event.completed>0&&event.total===0){reached=true;cancel.abort()}}};await expect(phase==="projectSnapshot"?mp4SnapshotToSqliteDatabase(snapshot,options):mp4SnapshotFromSqliteDatabase(database,options)).rejects.toThrow();expect(reached).toBe(true)}});
test("MP4 independently executable GraphQL retains every domain and exact wide counters",async()=>{for(const path of["../../🔗️.graphql","../../📝️text/🔗️.graphql"]){const sdl=await Bun.file(new URL(path,import.meta.url)).text();const schema=buildSchema("enum StateClass{ARTIFACT} directive @state(class:StateClass!) on FIELD_DEFINITION "+sdl+" type Query{snapshot:Mp4Snapshot!}");const result=graphqlSync({schema,source:"{snapshot{schema ftyp{majorBrand minorVersion compatibleBrands} movie{creationTime modificationTime timescale duration rate volume matrix nextTrackId title encoder} tracks{trackId timescale width height codec{format sps pps nalLengthSize extension{chromaFormat bitDepthLumaMinus8 bitDepthChromaMinus8 spsExt} hevc{generalProfileSpace generalTierFlag generalProfileIdc generalProfileCompatibilityFlags generalConstraintIndicatorFlags generalLevelIdc minSpatialSegmentationIdc parallelismType chromaFormatIdc bitDepthLumaMinus8 bitDepthChromaMinus8 avgFrameRate constantFrameRate numTemporalLayers temporalIdNested arrays{arrayCompleteness nalUnitType nalUnits}}} metadata{creationTime modificationTime flags duration layer alternateGroup volume matrix mediaDuration mediaCreationTime mediaModificationTime language quality handlerName edits{segmentDuration mediaTime mediaRateInteger mediaRateFraction} visual{dataReferenceIndex version revisionLevel vendor temporalQuality spatialQuality horizontalResolution verticalResolution frameCount compressorName depth colorTableId} color{colorType primaries transfer matrix fullRange} pixelAspectRatio{horizontalSpacing verticalSpacing} bitrate{bufferSize maximum average}} chunkSampleCounts samples{data duration ctsOffset sync}}}}",rootValue:{snapshot:fixture}});expect(result.errors).toBeUndefined();expect(result.data?.snapshot).toEqual(fixture)}});

